custom_css:
/* 星潮夜航 · reference reconstruction, modular external textures and ornaments. */

:root{--pr-ink:#f0f3ff;--pr-base:#081936;}
#sheld{background:var(--pr-base)!important;box-shadow:none!important;backdrop-filter:none!important;}
#chat{padding:0!important;gap:0!important;container-type:inline-size;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/surface.webp') center top/100% auto repeat-y!important;}
#chat .mes{position:relative;isolation:isolate;box-sizing:border-box;display:grid!important;grid-template-columns:minmax(0,48%) minmax(0,1fr);column-gap:12px;row-gap:16px;align-items:center!important;width:100%!important;max-width:720px!important;min-width:0!important;margin:0 auto 24px!important;padding:24px 20px 80px!important;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;color:var(--pr-ink)!important;backdrop-filter:none!important;}
#chat .mes>.mes_block{display:contents!important;}
#chat .mes::before,#chat .mes::after,#chat .mes>.mes_block::before,#chat .mes>.mes_block::after{content:'';position:absolute;pointer-events:none;background-repeat:no-repeat;background-size:contain;z-index:-1;}
#chat .mes .mesAvatarWrapper{grid-column:1;grid-row:1;position:relative!important;display:flex!important;flex-wrap:wrap;justify-content:space-around;align-items:center;align-content:start;gap:12px 2px;width:auto!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:0!important;}
#chat .mes .avatar{box-sizing:border-box;position:relative;flex:0 0 100%;width:100%!important;max-width:none!important;height:auto!important;aspect-ratio:1;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background:none!important;}
#chat .mes .avatar img{width:100%!important;height:100%!important;object-fit:cover!important;object-position:center 35%;border-radius:inherit!important;box-shadow:none!important;}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{position:static!important;width:auto!important;margin:0!important;padding:0!important;line-height:1.4!important;font-size:9px!important;color:var(--pr-ink)!important;opacity:.75;}
#chat .mes .ch_name{grid-column:2;grid-row:1;align-self:center;position:relative;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:stretch!important;gap:12px;width:100%!important;min-width:0!important;margin:0!important;padding:0!important;background:none!important;}
#chat .mes .ch_name>.flex1{display:flex!important;flex:none!important;justify-content:center;align-items:center;min-width:0;text-align:center;}
#chat .mes .name_text{display:block;max-width:100%;font-size:21px!important;line-height:1.4;font-weight:400;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .timestamp{font-size:9px;}
#chat .mes .mes_buttons{position:relative!important;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px!important;width:100%!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:4px 0!important;float:none!important;opacity:1!important;}
#chat .mes .mes_button{box-sizing:border-box;flex:0 0 auto;min-width:20px;min-height:26px;padding:2px!important;color:var(--pr-ink)!important;filter:none!important;text-shadow:none!important;}
#chat .mes .extraMesButtons{flex-wrap:wrap;justify-content:center;gap:4px;max-width:100%;flex-basis:100%;}
#chat .mes .mes_text{grid-column:1/-1;position:relative;box-sizing:border-box;width:100%!important;min-width:0!important;margin:0!important;padding:24px 15px 35px!important;min-height:200px;line-height:1.9!important;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .mes_text p{margin:.4em 0 .9em;}
#chat .mes .mes_text img,#chat .mes .mes_text video{max-width:100%;height:auto;}
#chat .mes .mes_text pre{max-width:100%;overflow-x:auto;}
#chat .mes .mes_text table{display:block;max-width:100%;overflow-x:auto;}
#chat .mes>.for_checkbox{position:absolute;left:4px;top:4px;}
#chat .mes>.swipe_left{position:absolute;left:10px;bottom:14px;z-index:3;}
#chat .mes>.swipe_right{position:absolute;right:10px;bottom:14px;z-index:3;}
#chat .mes .swipes-counter{color:var(--pr-ink);}
#top-bar{background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/surface.webp') center top/100% auto!important;box-shadow:none!important;border:0!important;}
#top-settings-holder{gap:0!important;}
#top-settings-holder>.drawer{min-width:0!important;flex:1 1 0;}
#top-settings-holder .drawer-toggle{display:flex;align-items:center;justify-content:center;min-height:38px;}
#top-settings-holder .drawer-icon{color:var(--pr-ink)!important;filter:none!important;opacity:1!important;font-size:22px!important;}
#send_form{position:relative;isolation:isolate;box-sizing:border-box;gap:8px!important;min-height:64px;padding:12px 18px!important;border:0!important;box-shadow:none!important;border-radius:0!important;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/surface.webp') center bottom/100% auto!important;}
#send_form::before{content:'';position:absolute;inset:5px;z-index:-1;pointer-events:none;background:rgba(255,255,255,.85);border-radius:20px;}
#send_textarea{background:transparent!important;color:var(--pr-ink)!important;border:0!important;box-shadow:none!important;min-height:36px;}
#send_textarea::placeholder{color:var(--pr-ink);opacity:.7;}
#send_form :is(i,.fa-solid,.fa-regular){color:var(--pr-ink)!important;filter:none!important;}
@media(min-width:700px){#chat .mes .name_text{font-size:25px!important;}#chat .mes .mes_text{font-size:18px;}}

#chat .mes{grid-template-columns:minmax(0,1fr);padding:0 0 clamp(110px,32vw,220px)!important;row-gap:0;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/surface.webp') center/100% auto repeat-y!important;}
#chat .mes .mesAvatarWrapper{grid-column:1;grid-row:1;gap:0;}
#chat .mes .avatar{aspect-ratio:1.52;border-radius:0!important;}
#chat .mes .avatar img{clip-path:ellipse(50% 34% at 50% 49%);}
#chat .mes .avatar::after{content:'';position:absolute;inset:0;pointer-events:none;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/hero.webp') center/contain no-repeat;}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{z-index:3;line-height:18px!important;margin-top:0!important;font-size:8px!important;}
#chat .mes .ch_name{grid-column:1;grid-row:2;box-sizing:border-box;display:flex!important;flex-direction:row!important;flex-wrap:wrap;gap:0!important;align-items:center!important;margin-top:-12px!important;padding:0 25px 12px!important;z-index:2;}
#chat .mes .ch_name>.flex1{flex:1 1 35%!important;justify-content:flex-start;text-align:left;}
#chat .mes .mes_buttons{flex:1 1 55%;max-width:65%!important;padding-bottom:14px!important;}
#chat .mes .mes_buttons::after{content:'';position:absolute;left:0;right:0;bottom:-8px;height:22px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/arc-line.svg') center/100% auto no-repeat;pointer-events:none;opacity:.8;z-index:-1;}
#chat .mes .mes_button{color:#e7ca81!important;font-size:16px;min-width:26px;}
#chat .mes .mes_text{min-height:150px;padding:26px 11% 34px!important;}
#chat .mes::after{left:0;right:0;bottom:0;height:clamp(150px,42vw,290px);background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/starry/sea.webp') center bottom/100% auto no-repeat;z-index:0;}
#send_form::before{inset:7px 10px;background:rgba(7,24,49,.88);border:1px solid #8aa7ca;border-radius:30px;}
#send_form{padding-block:17px!important;}

#top-settings-holder>.drawer:nth-child(1) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(1) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(2) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(2) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(3) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(3) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(4) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(4) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(5) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(5) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(6) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(6) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(7) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(7) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(8) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(8) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(9) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(9) .drawer-icon::before{opacity:0!important;}
#send_but{background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-1.webp') center/contain no-repeat!important;font-size:0!important;}#send_but::before{opacity:0;}
html,body,body *{scrollbar-width:none!important;scrollbar-gutter:auto!important;}
body::-webkit-scrollbar,body *::-webkit-scrollbar,html::-webkit-scrollbar{width:0!important;height:0!important;display:none!important;}
#chat{padding-inline:0!important;border-inline:0!important;box-sizing:border-box!important;background-attachment:scroll!important;}
#chat .mes .mes_buttons{overflow:visible!important;max-height:none!important;}

#chat .mes>:not(.mesAvatarWrapper):not(.mes_block):not(.for_checkbox):not(.swipe_left):not(.swipe_right),
#chat .mes>.mes_block>:not(.ch_name):not(.mes_text){grid-column:1/-1!important;min-width:0;max-width:100%;box-sizing:border-box;}
#chat .mes .mes_text{padding-left:8px!important;padding-right:8px!important;}

#chat .mes .mes_text{padding-left:12px!important;padding-right:12px!important;background:linear-gradient(90deg,rgba(6,22,48,.92),rgba(6,22,48,.96) 10%,rgba(6,22,48,.96) 90%,rgba(6,22,48,.92))!important;border:0!important;border-radius:0!important;color:#f0f3ff!important;}#chat .mes .ch_name{background:rgba(6,22,48,.9)!important;}#chat .mes .mes_button{border:1px solid #a9a078;border-radius:9px;background:#112a49;padding:4px!important;}
/* Painted controls: no CSS-drawn borders, no native scrollbar gutters. */
:root{--scrollbar-width:0px;--scrollbarWidth:0px;}
*,*::before,*::after{scrollbar-width:none!important;scrollbar-gutter:auto!important;}
*::-webkit-scrollbar,*::-webkit-scrollbar-track,*::-webkit-scrollbar-thumb,*::-webkit-scrollbar-corner{display:none!important;width:0!important;height:0!important;border:0!important;}
#chat{width:100%!important;padding-inline:0!important;margin-inline:0!important;border-inline:0!important;}
#chat .mes .mes_text{width:100%!important;max-width:100%!important;padding-inline:8px!important;margin-inline:0!important;box-sizing:border-box!important;}
#chat .mes .mes_buttons{display:flex!important;flex-direction:row!important;flex-wrap:wrap!important;align-items:center!important;justify-content:center!important;gap:5px!important;padding:5px 0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important;overflow:visible!important;}
#chat .mes .mes_buttons::after{display:none!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons),#chat .mes .extraMesButtons>.mes_button{box-sizing:border-box!important;flex:0 0 36px!important;width:36px!important;min-width:36px!important;max-width:36px!important;height:36px!important;min-height:36px!important;margin:0!important;padding:0!important;float:none!important;position:relative!important;inset:auto!important;transform:none!important;line-height:36px!important;text-align:center!important;border:0!important;border-radius:0!important;box-shadow:none!important;filter:none!important;text-shadow:none!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons){background:var(--painted-action,url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/0.webp')) center/contain no-repeat!important;font-size:0!important;color:transparent!important;opacity:1!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons)::before,#chat .mes .mes_buttons>:not(.extraMesButtons)::after{opacity:0!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons)>:is(img,svg,i,span){visibility:hidden!important;}
#chat .mes .mes_buttons .extraMesButtons{position:absolute!important;top:100%!important;right:0!important;left:auto!important;width:160px!important;max-width:160px!important;flex-basis:auto!important;gap:6px!important;padding:6px!important;z-index:9;}
#send_form :is(#options_button,#extensionsMenuButton){width:36px!important;height:38px!important;min-width:36px!important;flex:0 0 36px!important;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;font-size:0!important;filter:none!important;}
#send_form #options_button{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/7.webp')!important;}
#send_form #extensionsMenuButton{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/8.webp')!important;}
#send_form :is(#options_button,#extensionsMenuButton)::before,#send_form :is(#options_button,#extensionsMenuButton)::after{display:none!important;}
#send_form :is(#options_button,#extensionsMenuButton)>*{visibility:hidden!important;}
@media(max-width:700px){#sheld{width:100%!important;max-width:100%!important;left:0!important;right:0!important;margin-inline:0!important;border-inline:0!important;padding-inline:0!important;}#chat .mes{max-width:100%!important;}}

#chat .mes .mes_buttons>:is(.extraMesButtonsHint){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/0.webp');}
#chat .mes .mes_buttons>:is(.mes_bookmark,.mes_create_bookmark,.fa-flag){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/1.webp');}
#chat .mes .mes_buttons>:is(.mes_narrate,.fa-music,.fa-volume-high,.fa-bullhorn){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/2.webp');}
#chat .mes .mes_buttons>:is([title*="熊"],[title*="酒馆助手"],[title*="Tavern Helper"],[class*="tavern_helper"]){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/3.webp');}
#chat .mes .mes_buttons>:is(.mes_edit,.fa-pencil,.fa-pen){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/4.webp');}
#chat .mes .mes_buttons>:is(.mes_copy,.fa-layer-group,.fa-copy){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/5.webp');}
#chat .mes .mes_buttons>:is(.fa-chart-simple,.fa-chart-column,.fa-chart-bar,[title*="统计"],[class*="token_counter"]){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/starry/6.webp');}
#chat{background:#071b36!important;}
#chat .mes{background:#071b36!important;}
#chat .mes .ch_name,#chat .mes .mes_text{background:transparent!important;}
#chat .mes::after{mask-image:linear-gradient(transparent,#000 35%)!important;}
